const SLA_THRESHOLD_PCT = 99;
const WINDOW_MINUTES = 30;
const body = items[0].json;
const executions = Array.isArray(body.data) ? body.data : (Array.isArray(body) ? body : []);
const cutoff = Date.now() - WINDOW_MINUTES * 60 * 1000;
const windowRuns = executions.filter(e => new Date(e.startedAt).getTime() >= cutoff);
const total = windowRuns.length;
const success = windowRuns.filter(e => e.status === 'success' || e.finished === true).length;
const successRate = total > 0 ? Math.round((success / total) * 1000) / 10 : 100;
return [{ json: {
  checked_at: new Date().toISOString(),
  window_minutes: WINDOW_MINUTES,
  total_runs: total,
  successful_runs: success,
  success_rate_pct: successRate,
  sla_threshold_pct: SLA_THRESHOLD_PCT,
  breached: successRate < SLA_THRESHOLD_PCT && total > 0
} }];
